DO $salary$
DECLARE benchmarks jsonb := '{"Water Quality Laboratory Assistant": {"salary": {"min": 2.16, "max": 2.4}, "salaryEvidence": {"currency": "INR", "unit": "lakh per year", "country": "India", "checkedOn": "2026-11-18", "sourceUrl": "https://eptri.telangana.gov.in/public/images/careers/53211754394297.pdf", "benchmarkRole": "Laboratory Analyst / Project Faculty, analytical laboratory", "experienceBand": "0-2 years", "basis": "Annualised monthly consolidated pay: INR 18000-20000; two related laboratory posts", "isClosestRoleEstimate": true, "note": "Closest laboratory-role benchmark; this is not a salary survey of the exact seeded title."}}, "Water Treatment Operations Assistant": {"salary": {"min": 3.06, "max": 4.2}, "salaryEvidence": {"currency": "INR", "unit": "lakh per year", "country": "India", "checkedOn": "2026-11-18", "sourceUrl": "https://actrec.gov.in/sites/default/files/2026-04/Walk%20in%20%20Pump%20Operator%2015.04.2026.docx.pdf", "benchmarkRole": "Pump Operator with STP/WTP duties", "experienceBand": "Advertised eligibility plus experience", "basis": "Annualised monthly consolidated pay: INR 25510-35000; rounded to two decimals", "isClosestRoleEstimate": true, "note": "Indicative benchmark; actual offers vary by employer, location, qualifications and experience."}}, "Environmental Compliance Support Associate": {"salary": {"min": 6, "max": 12}, "salaryEvidence": {"currency": "INR", "unit": "lakh per year", "country": "India", "checkedOn": "2026-11-18", "sourceUrl": "https://www.adecco.com/en-in/-/media/project/adecco/adeccoin/image/employer/salary-guide/adecco%20india%20salary%20guid-2026.pdf", "benchmarkRole": "Compliance Officer", "experienceBand": "0-3 years", "basis": "Published annual salary guide band", "isClosestRoleEstimate": true, "note": "Broader corporate compliance benchmark, not an environmental-support-specific salary survey."}}, "Compliance Support Officer": {"salary": {"min": 6, "max": 12}, "salaryEvidence": {"currency": "INR", "unit": "lakh p