entry benchmark; specialist wastewater, membrane and optimisation titles may differ."}}, "Environmental Monitoring Analyst": {"salary": {"min": 4, "max": 8}, "salaryEvidence": {"currency": "INR", "unit": "lakh per year", "country": "India", "checkedOn": "2026-11-18", "sourceUrl": "https://www.adecco.com/en-in/-/media/project/adecco/adeccoin/image/employer/salary-guide/adecco%20india%20salary%20guid-2026.pdf", "benchmarkRole": "Data Analyst", "experienceBand": "0-3 years", "basis": "Published annual salary guide band", "isClosestRoleEstimate": true, "note": "General data-analyst benchmark; environmental-sector salaries may differ."}}, "Environmental Data Analyst": {"salary": {"min": 4, "max": 8}, "salaryEvidence": {"currency": "INR", "unit": "lakh per year", "country": "India", "checkedOn": "2026-11-18", "sourceUrl": "https://www.adecco.com/en-in/-/media/project/adecco/adeccoin/image/employer/salary-guide/adecco%20india%20salary%20guid-2026.pdf", "benchmarkRole": "Data Analyst", "experienceBand": "0-3 years", "basis": "Published annual salary guide band", "isClosestRoleEstimate": true, "note": "General data-analyst benchmark; environmental-sector salaries may differ."}}, "Field Technician": {"salary": {"min": 1.57, "max": 3.48}, "salaryEvidence": {"currency": "INR", "unit": "lakh per year", "country": "India", "checkedOn": "2026-11-18", "sourceUrl": "https://in.indeed.com/career/field-technician/salaries", "benchmarkRole": "Field Technician", "experienceBand": "All experience levels in source", "basis": "Annualised monthly base range: INR 13121-29012; rounded to two decimals", "isClosestRoleEstimate": false, "note": "Indicative benchmark; actual offers vary by employer, location, qualifications and experience."}}, "Water Resources / WASH Project Associate": {"salary": {"min": 4.84, "max": 5.46}, "salaryEvidence": {"currency": "INR", "unit": "lakh per year", "country": "India", "checkedOn": "2026-11-18", "sourceUrl": "https://cms.nias.res.in/sites/default/filesefs/files/about/Project_Associates_Vacancy-May_2026.pdf", "benchmarkRole": "Natural-resource / social-science Project Associate I-II", "experienceBand": "Source requires relevant postgraduate qualifications", "basis": "Annualised consolidated pay including 30% HRA: INR 40300-45500 monthly", "isClosestRoleEstimate": true, "note": "Related natural-resource/community project posts; levels and qualifications vary, and this is not a guaranteed MBA starting salary."}}, "Water Project Finance & Procurement Associate": {"salary": {"min": 6, "max": 7.2}, "salaryEvidence": {"currency": "INR", "unit": "lakh per year", "country": "India", "checkedOn": "2026-11-18", "sourceUrl": "https://fremaa.assam.gov.in/sites/default/files/swf_utility_folder/departments/fremaa_webcomindia_org_oid_4/portlet/level_1/files/tor_for_procurement_associates_compressed.pdf", "benchmarkRole": "Procurement Associate, flood and river management agency", "experienceBand": "Experienced contractual appointment; May 2023 terms", "basis": "Annualised monthly remuneration: INR 50000-60000 inclusive of local taxes", "isClosestRoleEstimate": true, "note": "Related river-project procurement appointment; experienced-role benchmark, not a fresher guarantee."}}, "Water Monitoring Technology Associate": {"salary": {"min": 1.69, "max": 5.83}, "salaryEvidence": {"currency": "INR", "unit": "lakh per year", "country": "India", "checkedOn": "2026-11-18", "sourceUrl": "https://in.indeed.com/career/instrument-technician/salaries", "benchmarkRole": "Instrument Technician", "experienceBand": "All experience levels in source", "basis": "Annualised monthly base range: INR 14078-48553; rounded to two decimals", "isClosestRoleEstimate": true, "note": "Instrumentation benchmark for sensor-monitoring support; the exact water role is not surveyed."}}, "Business Analyst": {"salary": {"min": 4.4, "max": 10}, "salaryEvidence": {"currency": "INR", "unit": "lakh per year", "country": "India", "checkedOn": "2026-11-18", "sourceUrl": "https://flexiple.com/salary/business-analyst", "benchmarkRole": "Business Analyst", "experienceBand": "0-3 years", "basis": "Published middle-50-percent annual CTC range", "isClosestRoleEstimate": false, "note": "Indicative benchmark; actual offers vary by employer, location, qualifications and experience."}}, "Payment Operations Analyst": {"salary": {"min": 3, "max": 16.2}, "salaryEvidence": {"currency": "INR", "unit": "lakh per year", "country": "India", "checkedOn": "2026-11-18", "sourceUrl": "https://www.glassdoor.co.in/Salaries/india-payment-operations-analyst-salary-SRCH_IL.0%2C5_IN115_KO6%2C32.htm", "benchmarkRole": "Payment Operations Analyst", "experienceBand": "All experience levels; small reported sample", "basis": "Published annual base-pay range", "isClosestRoleEstimate": false, "note": "Nine reported salaries in source; broad range includes experienced workers and is not a fresher-only benchmark."}}, "Workforce Planning Analyst": {"salary": {"min": 4.2, "max": 7.92}, "salaryEvidence": {"currency": "INR", "unit": "lakh per year", "country": "India", "checkedOn": "2026-11-18", "sourceUrl": "https://www.glassdoor.com/Salaries/india-workforce-management-analyst-salary-SRCH_IL.0%2C5_IN115_KO6%2C34.htm", "benchmarkRole": "Workforce Management Analyst", "experienceBand": "All experience levels in source", "basis": "Published annual total-pay middle-50-percent range", "isClosestRoleEstimate": true, "note": "Indicative benchmark; actual offers vary by employer, location, qualifications and experience."}}}'::jsonb;
 fit jsonb; groups jsonb := '{}'::jsonb; group_row record;
 option_row record; options jsonb; evidence jsonb; role_count integer := 0;
BEGIN
 SELECT r.career_fit INTO STRICT fit FROM public.personal_assessment_results r
 JOIN public.learners l ON l.id=r.learner_id
 WHERE r.id='025d910f-2ea2-5fee-b28b-b756df343348'::uuid AND l.email='arjun.srinivasan27@example.com' AND l.learner_type='college_student'
 FOR UPDATE OF r;
 FOR group_row IN SELECT key,value FROM jsonb_each(fit->'specificOptions') LOOP
  options := '[]'::jsonb;
  FOR option_row IN SELECT value FROM jsonb_array_elements(group_row.value) WITH ORDINALITY a(value,position) ORDER BY position LOOP
   evidence := benchmarks->(option_row.value->>'name');
   IF evidence IS NULL THEN RAISE EXCEPTION 'Missing sourced salary for %',option_row.value->>'name'; END IF;
   options := options || jsonb_build_array(option_row.value || evidence);
   role_count := role_count+1;
  END LOOP;
  groups := jsonb_set(groups,ARRAY[group_row.key],options,true);
 END LOOP;
 IF role_count<>9 THEN RAISE EXCEPTION 'Expected 9 college roles, found %',role_count; END IF;
 fit := jsonb_set(fit,'{specificOptions}',groups);
 UPDATE public.personal_assessment_results SET career_fit=fit,
 gemini_results=jsonb_set(coalesce(gemini_results,'{}'::jsonb),'{careerFit}',fit)
 WHERE id='025d910f-2ea2-5fee-b28b-b756df343348'::uuid;
END $salary$;
COMMIT;
